SELECT i.*, u.username, u.avatar AS user_avatar, u.student_no, u.department, c.category_name,
(SELECT COUNT(1) FROM favorite f WHERE f.item_id = i.id AND f.user_id = #{currentUserId}) AS favorited
0 AS favorited FROM idle_item i INNER JOIN sys_user u ON i.user_id = u.id INNER JOIN item_category c ON i.category_id = c.id WHERE i.id = #{id}

SELECT i.*, u.username, u.avatar AS user_avatar, u.student_no, u.department, c.category_name,
(SELECT COUNT(1) FROM favorite f WHERE f.item_id = i.id AND f.user_id = #{currentUserId}) AS favorited
0 AS favorited
FROM idle_item i INNER JOIN sys_user u ON i.user_id = u.id INNER JOIN item_category c ON i.category_id = c.id WHERE i.status = 1 AND i.audit_status = 1
AND i.category_id = #{categoryId}
AND (i.item_name LIKE CONCAT('%', #{keyword}, '%') OR i.item_desc LIKE CONCAT('%', #{keyword}, '%'))
AND i.item_condition = #{itemCondition}
AND i.campus = #{campus}
ORDER BY i.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM idle_item
WHERE status = 1 AND audit_status = 1

    AND category_id = #{categoryId}


    AND (item_name LIKE CONCAT('%', #{keyword}, '%')
         OR item_desc LIKE CONCAT('%', #{keyword}, '%'))


    AND item_condition = #{itemCondition}


    AND campus = #{campus}
